before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <random>
int main() {
    std::mt19937 engine{42};
    std::uniform_int_distribution<int> die{1, 6};
    bool inRange = true;
    for (int i = 0; i < 20; ++i) {
        int roll = die(engine);
        inRange = inRange && (roll >= 1 && roll <= 6);
    }
    std::cout << inRange << "\n";
}
```

